function abbreviateProduct(left: number, right: number): string {
    let product = BigInt(1);

    for (let i = left; i <= right; i++) {
        product *= BigInt(i);
    }

    const ten = BigInt(10);
    let trailingZeros = 0;

    while (product % ten === BigInt(0)) {
        product /= ten;
        trailingZeros++;
    }

    const value = product.toString();

    if (value.length <= 10) {
        return value + "e" + trailingZeros;
    }

    return value.slice(0, 5) + "..." + value.slice(-5) + "e" + trailingZeros;
};
