function clumsy(n: number): number {
    const stack: number[] = [n];
    let value = n - 1;
    let operation = 0;

    while (value >= 1) {
        if (operation === 0) {
            stack[stack.length - 1] *= value;
        } else if (operation === 1) {
            stack[stack.length - 1] = Math.floor(stack[stack.length - 1] / value);
        } else if (operation === 2) {
            stack.push(value);
        } else {
            stack.push(-value);
        }

        value--;
        operation = (operation + 1) % 4;
    }

    return stack.reduce((sum, current) => sum + current, 0);
};
