function numSmallerByFrequency(queries: string[], words: string[]): number[] {
    const frequency = (s: string): number => {
        let minChar = '{';
        for (const ch of s) {
            if (ch < minChar) minChar = ch;
        }

        let count = 0;
        for (const ch of s) {
            if (ch === minChar) count++;
        }
        return count;
