    const counts = new Array<number>(11).fill(0);

    for (const word of words) {
        counts[frequency(word)]++;
    }

    for (let i = 9; i >= 1; i--) {
        counts[i] += counts[i + 1];
    }

    return queries.map(query => counts[frequency(query) + 1]);
}
