function regionsBySlashes(grid: string[]): number {
    const n = grid.length;
    const total = n * n * 4;
    const parent = Array.from({ length: total }, (_, i) => i);

    const find = (x: number): number => {
        while (parent[x] !== x) {
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        return x;
    };

    const union = (a: number, b: number): void => {
        const ra = find(a);
        const rb = find(b);
        if (ra !== rb) parent[ra] = rb;
    };

    const id = (r: number, c: number, part: number): number =>
        (r * n + c) * 4 + part;

    for (let r = 0; r < n; r++) {
        for (let c = 0; c < n; c++) {
            const ch = grid[r][c];
            const top = id(r, c, 0);
            const right = id(r, c, 1);
            const bottom = id(r, c, 2);
            const left = id(r, c, 3);

            if (ch === '/') {
                union(top, right);
                union(bottom, left);
            } else if (ch === '\\') {
                union(top, left);
                union(right, bottom);
            } else {
                union(top, right);
                union(right, bottom);
                union(bottom, left);
            }

            if (r + 1 < n) {
                union(bottom, id(r + 1, c, 0));
            }
            if (c + 1 < n) {
                union(right, id(r, c + 1, 3));
            }
        }
    }

    const roots = new Set<number>();
    for (let i = 0; i < total; i++) {
        roots.add(find(i));
    }

    return roots.size;
};
