function getCoprimes(nums: number[], edges: number[][]): number[] {
    const n = nums.length;
    const graph: number[][] = Array.from({ length: n }, () => []);

    for (const [u, v] of edges) {
        graph[u].push(v);
        graph[v].push(u);
    }

    const gcd = (a: number, b: number): number => {
        while (b !== 0) {
            const t = a % b;
            a = b;
            b = t;
        }
        return a;
    };

    const coprime: boolean[][] = Array.from({ length: 51 }, () =>
        Array(51).fill(false)
    );

    for (let a = 1; a <= 50; a++) {
        for (let b = 1; b <= 50; b++) {
            coprime[a][b] = gcd(a, b) === 1;
        }
    }

    const paths: number[][] = Array.from({ length: 51 }, () => []);
    const ans: number[] = Array(n).fill(-1);

    const stack: [number, number, boolean][] = [[0, -1, false]];

    while (stack.length > 0) {
        const [node, parent, exiting] = stack.pop()!;

        if (!exiting) {
            const value = nums[node];
            let best = -1;

            for (let candidate = 1; candidate <= 50; candidate++) {
                if (coprime[value][candidate] && paths[candidate].length > 0) {
                    const ancestor = paths[candidate][paths[candidate].length - 1];
                    if (best === -1 || ancestor > best) {
                        best = ancestor;
                    }
                }
            }

            ans[node] = best;
            paths[value].push(node);

            stack.push([node, parent, true]);

            for (const next of graph[node]) {
                if (next !== parent) {
                    stack.push([next, node, false]);
                }
            }
        } else {
            paths[nums[node]].pop();
        }
    }

    return ans;
};
