function hitBricks(grid: number[][], hits: number[][]): number[] {
    const m = grid.length;
    const n = grid[0].length;
    const original = grid.map(row => row.slice());
    const total = m * n;
    const top = total;

    const parent = Array.from({ length: total + 1 }, (_, i) => i);
    const size = new Array(total + 1).fill(1);

    function find(x: number): number {
        while (parent[x] !== x) {
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        return x;
    }

    function union(a: number, b: number): void {
        let ra = find(a);
        let rb = find(b);

        if (ra === rb) return;

        if (size[ra] < size[rb]) {
            const temp = ra;
            ra = rb;
            rb = temp;
        }

        parent[rb] = ra;
        size[ra] += size[rb];
    }

    for (const [r, c] of hits) {
        if (grid[r][c] === 1) {
            grid[r][c] = 0;
        }
    }

    const directions = [[1, 0], [-1, 0], [0, 1], [0, -1]];

    for (let r = 0; r < m; r++) {
        for (let c = 0; c < n; c++) {
            if (grid[r][c] === 0) continue;

            const index = r * n + c;

            if (r === 0) {
                union(index, top);
            }

            for (const [dr, dc] of directions) {
                const nr = r + dr;
                const nc = c + dc;

                if (
                    nr >= 0 &&
                    nr < m &&
                    nc >= 0 &&
                    nc < n &&
                    grid[nr][nc] === 1
                ) {
                    union(index, nr * n + nc);
                }
            }
        }
    }

    const result = new Array(hits.length).fill(0);

    for (let i = hits.length - 1; i >= 0; i--) {
        const [r, c] = hits[i];

        if (original[r][c] === 0) continue;

        const before = size[find(top)];
        const index = r * n + c;
        grid[r][c] = 1;

        if (r === 0) {
            union(index, top);
        }

        for (const [dr, dc] of directions) {
            const nr = r + dr;
            const nc = c + dc;

            if (
                nr >= 0 &&
                nr < m &&
                nc >= 0 &&
                nc < n &&
                grid[nr][nc] === 1
            ) {
                union(index, nr * n + nc);
            }
        }

        const after = size[find(top)];
        result[i] = Math.max(0, after - before - 1);
    }

    return result;
}
