function countMaxOrSubsets(nums: number[]): number {
    let maxOr = 0;
    let count = 0;
    const total = 1 << nums.length;

    for (let mask = 1; mask < total; mask++) {
        let currentOr = 0;

        for (let i = 0; i < nums.length; i++) {
            if ((mask & (1 << i)) !== 0) {
                currentOr |= nums[i];
            }
        }

        if (currentOr > maxOr) {
            maxOr = currentOr;
            count = 1;
        } else if (currentOr === maxOr) {
            count++;
        }
    }

    return count;
};
