function isCousins(root: TreeNode | null, x: number, y: number): boolean {
    if (root === null) return false;

    const queue: Array<[TreeNode, TreeNode | null]> = [[root, null]];
    let index = 0;

    while (index < queue.length) {
        const levelEnd = queue.length;
        let parentX: TreeNode | null = null;
        let parentY: TreeNode | null = null;

        while (index < levelEnd) {
            const [node, parent] = queue[index++];

            if (node.val === x) parentX = parent;
            if (node.val === y) parentY = parent;

            if (node.left !== null) {
                queue.push([node.left, node]);
            }
            if (node.right !== null) {
                queue.push([node.right, node]);
            }
        }

        if (parentX !== null || parentY !== null) {
            return parentX !== null && parentY !== null && parentX !== parentY;
        }
    }

    return false;
};
