    private maxSize: number;
    private stack: number[];

    constructor(maxSize: number) {
        this.maxSize = maxSize;
        this.stack = [];
    }

    push(x: number): void {
        if (this.stack.length < this.maxSize) {
            this.stack.push(x);
        }
