function eventualSafeNodes(graph: number[][]): number[] {
    const n = graph.length;
    const reverse: number[][] = Array.from({ length: n }, () => []);
    const outdegree = new Array<number>(n).fill(0);
    const queue: number[] = [];

    for (let i = 0; i < n; i++) {
        outdegree[i] = graph[i].length;

        if (outdegree[i] === 0) {
            queue.push(i);
        }

        for (const next of graph[i]) {
            reverse[next].push(i);
        }
    }

    const safe = new Array<boolean>(n).fill(false);
    let head = 0;

    while (head < queue.length) {
        const node = queue[head++];
        safe[node] = true;

        for (const prev of reverse[node]) {
            outdegree[prev]--;

            if (outdegree[prev] === 0) {
                queue.push(prev);
            }
        }
    }

    const result: number[] = [];
    for (let i = 0; i < n; i++) {
        if (safe[i]) {
            result.push(i);
        }
    }

    return result;
}
