    const m = nums.length;
    const fullMask = (1 << m) - 1;
    const gcd = (a: number, b: number): number => {
        while (b !== 0) {
            const t = a % b;
            a = b;
            b = t;
        }
        return a;
    };

    const pairGcd: number[][] = Array.from({ length: m }, () => Array(m).fill(0));
    for (let i = 0; i < m; i++) {
        for (let j = i + 1; j < m; j++) {
            pairGcd[i][j] = gcd(nums[i], nums[j]);
        }
    }

    const dp = new Int32Array(1 << m);
    dp.fill(-1);
    dp[fullMask] = 0;

    const countBits = (mask: number): number => {
        let count = 0;
        while (mask !== 0) {
            mask &= mask - 1;
            count++;
        }
        return count;
    };

    const solve = (mask: number): number => {
        if (dp[mask] !== -1) return dp[mask];

        const operation = countBits(mask) / 2 + 1;
        let best = 0;

        for (let i = 0; i < m; i++) {
            if ((mask & (1 << i)) !== 0) continue;

            for (let j = i + 1; j < m; j++) {
                if ((mask & (1 << j)) !== 0) continue;

                const nextMask = mask | (1 << i) | (1 << j);
                const score = operation * pairGcd[i][j] + solve(nextMask);
                best = Math.max(best, score);
            }
        }

        dp[mask] = best;
        return best;
    };

    return solve(0);
