function maximumANDSum(nums: number[], numSlots: number): number {
    const powers: number[] = new Array(numSlots);
    powers[0] = 1;

    for (let i = 1; i < numSlots; i++) {
        powers[i] = powers[i - 1] * 3;
    }

    const stateCount = Math.pow(3, numSlots);
    let dp = new Array<number>(stateCount).fill(-Infinity);
    dp[0] = 0;

    for (const num of nums) {
        const next = new Array<number>(stateCount).fill(-Infinity);

        for (let state = 0; state < stateCount; state++) {
            if (dp[state] === -Infinity) continue;

            for (let slot = 0; slot < numSlots; slot++) {
                const digit = Math.floor(state / powers[slot]) % 3;

                if (digit < 2) {
                    const newState = state + powers[slot];
                    const value = dp[state] + (num & (slot + 1));

                    if (value > next[newState]) {
                        next[newState] = value;
                    }
                }
            }
        }

        dp = next;
    }

    return Math.max(...dp);
