function maxTotalFruits(fruits: number[][], startPos: number, k: number): number {
    let left = 0;
    let current = 0;
    let answer = 0;

    const cost = (l: number, r: number): number => {
        const leftPos = fruits[l][0];
        const rightPos = fruits[r][0];

        if (rightPos <= startPos) {
            return startPos - leftPos;
        }

        if (leftPos >= startPos) {
            return rightPos - startPos;
        }

        const leftDistance = startPos - leftPos;
        const rightDistance = rightPos - startPos;

        return Math.min(
            leftDistance * 2 + rightDistance,
            leftDistance + rightDistance * 2
        );
    };

    for (let right = 0; right < fruits.length; right++) {
        current += fruits[right][1];

        while (left <= right && cost(left, right) > k) {
            current -= fruits[left][1];
            left++;
        }

        answer = Math.max(answer, current);
    }

    return answer;
}
