function maximumBeauty(flowers: number[], newFlowers: number, target: number, full: number, partial: number): number {
    const n = flowers.length;
    const arr = flowers.map(value => Math.min(value, target));
    arr.sort((a, b) => a - b);

    const prefix = new Array<number>(n + 1).fill(0);
    for (let i = 0; i < n; i++) {
        prefix[i + 1] = prefix[i] + arr[i];
    }

    let baseComplete = 0;
    while (baseComplete < n && arr[baseComplete] >= target) {
        baseComplete++;
    }

    const getPartialLevel = (count: number, budget: number): number => {
        let low = 0;
        let high = target - 1;

        while (low <= high) {
            const level = Math.floor((low + high) / 2);

            let left = 0;
            let right = count;
            while (left < right) {
                const mid = Math.floor((left + right) / 2);
                if (arr[mid] <= level) {
                    left = mid + 1;
                } else {
                    right = mid;
                }
            }

            const needed = level * left - prefix[left];

            if (needed <= budget) {
                low = level + 1;
            } else {
                high = level - 1;
            }
        }

        return high;
    };

    let answer = 0;
    let completeCost = 0;

    for (let complete = baseComplete; complete <= n; complete++) {
        if (complete > baseComplete) {
            completeCost += target - arr[n - complete];
        }

        if (completeCost > newFlowers) {
            break;
        }

        const incomplete = n - complete;
        let beauty = complete * full;

        if (incomplete > 0) {
            const level = getPartialLevel(incomplete, newFlowers - completeCost);
            beauty += level * partial;
        }

        answer = Math.max(answer, beauty);
    }

    return answer;
}
