function minMalwareSpread(graph: number[][], initial: number[]): number {
    const n = graph.length;
    const isInitial = new Array<boolean>(n).fill(false);

    for (const node of initial) {
        isInitial[node] = true;
    }

    const visited = new Array<boolean>(n).fill(false);
    const saved = new Array<number>(n).fill(0);

    for (let start = 0; start < n; start++) {
        if (isInitial[start] || visited[start]) continue;

        const queue: number[] = [start];
        visited[start] = true;
        let head = 0;
        let size = 0;
        const sources = new Set<number>();

        while (head < queue.length) {
            const node = queue[head++];
            size++;

            for (let next = 0; next < n; next++) {
                if (graph[node][next] === 0) continue;

                if (isInitial[next]) {
                    sources.add(next);
                } else if (!visited[next]) {
                    visited[next] = true;
                    queue.push(next);
                }
            }
        }

        if (sources.size === 1) {
            const source = sources.values().next().value as number;
            saved[source] += size;
        }
    }

    let answer = initial[0];
    for (const node of initial) {
        if (
            saved[node] > saved[answer] ||
            (saved[node] === saved[answer] && node < answer)
        ) {
            answer = node;
        }
    }

    return answer;
};
