function minAreaRect(points: number[][]): number {
    const columns = new Map<number, number[]>();

    for (const [x, y] of points) {
        if (!columns.has(x)) columns.set(x, []);
        columns.get(x)!.push(y);
    }

    const xs = Array.from(columns.keys()).sort((a, b) => a - b);
    const lastX = new Map<string, number>();
    let result = Infinity;

    for (const x of xs) {
        const ys = columns.get(x)!;
        ys.sort((a, b) => a - b);

        for (let i = 0; i < ys.length; i++) {
            for (let j = i + 1; j < ys.length; j++) {
                const key = `${ys[i]},${ys[j]}`;

                if (lastX.has(key)) {
                    const width = x - lastX.get(key)!;
                    const height = ys[j] - ys[i];
                    result = Math.min(result, width * height);
                }

                lastX.set(key, x);
            }
        }
    }

    return result === Infinity ? 0 : result;
};
