function minOperations(s: string): number {
    let changesStartingWithZero = 0;
    let changesStartingWithOne = 0;

    for (let i = 0; i < s.length; i++) {
        const expectedZero = i % 2 === 0 ? '0' : '1';
        const expectedOne = i % 2 === 0 ? '1' : '0';

