function minDays(bloomDay: number[], m: number, k: number): number {
    const n = bloomDay.length;

    if (m * k > n) {
        return -1;
    }

    let left = 1;
    let right = 0;

    for (const day of bloomDay) {
        right = Math.max(right, day);
    }

    const canMake = (days: number): boolean => {
        let consecutive = 0;
        let bouquets = 0;

        for (const bloom of bloomDay) {
            if (bloom <= days) {
                consecutive++;

                if (consecutive === k) {
                    bouquets++;
                    consecutive = 0;

                    if (bouquets >= m) {
                        return true;
                    }
                }
            } else {
                consecutive = 0;
            }
        }

        return false;
    };

    let answer = -1;

    while (left <= right) {
        const mid = Math.floor((left + right) / 2);

        if (canMake(mid)) {
            answer = mid;
            right = mid - 1;
        } else {
            left = mid + 1;
        }
    }

    return answer;
}
