function minSessions(tasks: number[], sessionTime: number): number {
    const n = tasks.length;
    const totalMasks = 1 << n;
    const sessions = new Array<number>(totalMasks).fill(Infinity);
    const used = new Array<number>(totalMasks).fill(Infinity);

    sessions[0] = 1;
    used[0] = 0;

    for (let mask = 0; mask < totalMasks; mask++) {
        for (let i = 0; i < n; i++) {
            if ((mask & (1 << i)) !== 0) continue;

            const nextMask = mask | (1 << i);
            let nextSessions = sessions[mask];
            let nextUsed: number;

            if (used[mask] + tasks[i] <= sessionTime) {
                nextUsed = used[mask] + tasks[i];
            } else {
                nextSessions++;
                nextUsed = tasks[i];
