function nextBeautifulNumber(n: number): number {
    let answer = Infinity;
    const counts = new Array<number>(8).fill(0);

    for (let mask = 1; mask < (1 << 7); mask++) {
        let length = 0;

        for (let digit = 1; digit <= 7; digit++) {
            if ((mask & (1 << (digit - 1))) !== 0) {
                counts[digit] = digit;
                length += digit;
            } else {
                counts[digit] = 0;
            }
        }

        if (length > 7) continue;

        const build = (value: number, remaining: number): void => {
            if (remaining === 0) {
                if (value > n && value < answer) {
                    answer = value;
                }
                return;
