            for (let digit = 1; digit <= 7; digit++) {
                if (counts[digit] > 0) {
                    counts[digit]--;
                    build(value * 10 + digit, remaining - 1);
                    counts[digit]++;
                }
            }
        };

        build(0, length);
    }

    return answer;
};
