function numOfWays(nums: number[]): number {
    const MOD = 1000000007;
    const BASE = 32768;

    function mulMod(a: number, b: number): number {
        const high = Math.floor(a / BASE);
        const low = a - high * BASE;

        const partHigh = (high * b) % MOD;
        const partLow = (low * b) % MOD;

        return (partHigh * BASE + partLow) % MOD;
    }

    const n = nums.length;
    const combinations: number[][] = Array.from({ length: n + 1 }, () => []);

    for (let i = 0; i <= n; i++) {
        combinations[i] = new Array(i + 1).fill(1);
        for (let j = 1; j < i; j++) {
            combinations[i][j] =
                (combinations[i - 1][j - 1] + combinations[i - 1][j]) % MOD;
        }
    }

    function countWays(values: number[]): number {
        if (values.length <= 2) {
            return 1;
        }

        const root = values[0];
        const left: number[] = [];
        const right: number[] = [];

        for (let i = 1; i < values.length; i++) {
            if (values[i] < root) {
                left.push(values[i]);
            } else {
                right.push(values[i]);
            }
        }

        const leftWays = countWays(left);
        const rightWays = countWays(right);
        const interleavings = combinations[left.length + right.length][left.length];

        return mulMod(interleavings, mulMod(leftWays, rightWays));
    }

    return (countWays(nums) - 1 + MOD) % MOD;
};
