function canPartitionKSubsets(nums: number[], k: number): boolean {
    const total = nums.reduce((sum, value) => sum + value, 0);

    if (total % k !== 0) return false;

    const target = total / k;
    nums.sort((a, b) => b - a);

    if (nums[0] > target) return false;

    const n = nums.length;
    const fullMask = (1 << n) - 1;
    const subsetSum = new Array<number>(1 << n).fill(0);

    for (let mask = 1; mask <= fullMask; mask++) {
        const bit = mask & -mask;
        const index = Math.log2(bit);
        subsetSum[mask] = subsetSum[mask ^ bit] + nums[index];
    }

    const memo = new Int8Array(1 << n);
    memo.fill(-1);

    const dfs = (mask: number): boolean => {
        if (mask === fullMask) return true;
        if (memo[mask] !== -1) return memo[mask] === 1;

        const currentSum = subsetSum[mask] % target;

        for (let i = 0; i < n; i++) {
            if ((mask & (1 << i)) !== 0) continue;
            if (currentSum + nums[i] > target) continue;

            if (dfs(mask | (1 << i))) {
                memo[mask] = 1;
                return true;
            }

            if (currentSum === 0) break;
        }

        memo[mask] = 0;
        return false;
    };

    return dfs(0);
}
