function maxSizeSlices(slices: number[]): number {
    const length = slices.length;
    const picks = length / 3;

    const solveLinear = (start: number, end: number): number => {
        const count = end - start + 1;
        const dp: number[][] = Array.from(
            { length: picks + 1 },
            () => Array(count + 1).fill(Number.NEGATIVE_INFINITY)
        );

        for (let i = 0; i <= count; i++) {
            dp[0][i] = 0;
        }

        for (let i = 1; i <= count; i++) {
            const value = slices[start + i - 1];

            for (let j = 1; j <= picks; j++) {
                dp[j][i] = dp[j][i - 1];

                if (i === 1) {
                    if (j === 1) {
                        dp[j][i] = Math.max(dp[j][i], value);
                    }
                } else {
                    dp[j][i] = Math.max(
                        dp[j][i],
                        dp[j - 1][i - 2] + value
                    );
                }
            }
        }

        return dp[picks][count];
    };

    return Math.max(
        solveLinear(0, length - 2),
        solveLinear(1, length - 1)
    );
}
