function isScramble(s1: string, s2: string): boolean {
    const n = s1.length;
    if (n !== s2.length) return false;

    const prefix1 = Array.from({ length: n + 1 }, () => new Int32Array(26));
    const prefix2 = Array.from({ length: n + 1 }, () => new Int32Array(26));

    for (let i = 0; i < n; i++) {
        prefix1[i + 1].set(prefix1[i]);
        prefix2[i + 1].set(prefix2[i]);

        prefix1[i + 1][s1.charCodeAt(i) - 97]++;
        prefix2[i + 1][s2.charCodeAt(i) - 97]++;
    }

    const memo = new Uint8Array(n * n * (n + 1));

    const sameCharacters = (i: number, j: number, len: number): boolean => {
        for (let c = 0; c < 26; c++) {
            if (
                prefix1[i + len][c] - prefix1[i][c] !==
                prefix2[j + len][c] - prefix2[j][c]
            ) {
                return false;
            }
        }
        return true;
    };

    const index = (i: number, j: number, len: number): number =>
        (i * n + j) * (n + 1) + len;

    const dfs = (i: number, j: number, len: number): boolean => {
        const stateIndex = index(i, j, len);
        if (memo[stateIndex] !== 0) {
            return memo[stateIndex] === 1;
