function shiftGrid(grid: number[][], k: number): number[][] {
    const m = grid.length;
    const n = grid[0].length;
    const total = m * n;
    const result: number[][] = Array.from({ length: m }, () => Array(n).fill(0));

    k %= total;

    for (let i = 0; i < m; i++) {
        for (let j = 0; j < n; j++) {
            const oldIndex = i * n + j;
            const newIndex = (oldIndex + k) % total;
            result[Math.floor(newIndex / n)][newIndex % n] = grid[i][j];
        }
    }

    return result;
};
