function medianSlidingWindow(nums: number[], k: number): number[] {
    type Item = { v: number; id: number };

    const low: Item[] = [];
    const high: Item[] = [];
    const deleted = new Set<number>();
    const side: number[] = new Array(nums.length);

    const maxBefore = (a: Item, b: Item): boolean =>
        a.v !== b.v ? a.v > b.v : a.id > b.id;

    const minBefore = (a: Item, b: Item): boolean =>
        a.v !== b.v ? a.v < b.v : a.id < b.id;

    function push(heap: Item[], item: Item, before: (a: Item, b: Item) => boolean): void {
        heap.push(item);
        let i = heap.length - 1;

        while (i > 0) {
            const p = (i - 1) >> 1;
            if (before(heap[p], heap[i])) break;
            [heap[p], heap[i]] = [heap[i], heap[p]];
            i = p;
        }
    }

    function pop(heap: Item[], before: (a: Item, b: Item) => boolean): Item {
        const result = heap[0];
        const last = heap.pop()!;

        if (heap.length > 0) {
            heap[0] = last;
            let i = 0;

            while (true) {
                let best = i;
                const left = i * 2 + 1;
                const right = i * 2 + 2;

                if (left < heap.length && !before(heap[best], heap[left])) {
                    best = left;
                }
                if (right < heap.length && !before(heap[best], heap[right])) {
                    best = right;
                }
                if (best === i) break;

                [heap[i], heap[best]] = [heap[best], heap[i]];
                i = best;
            }
        }

        return result;
