            deleted.delete(heap[0].id);
            pop(heap, heap === low ? maxBefore : minBefore);
        }
    }

    let lowSize = 0;
    let highSize = 0;

    function rebalance(): void {
        prune(low);
        prune(high);

        while (lowSize > highSize + 1) {
