function minStickers(stickers: string[], target: string): number {
    const m = target.length;
    const fullMask = (1 << m) - 1;
    const stickerCounts: number[][] = [];

    for (const sticker of stickers) {
        const count = new Array<number>(26).fill(0);
        for (const ch of sticker) {
            count[ch.charCodeAt(0) - 97]++;
        }
        stickerCounts.push(count);
    }

    const dp = new Array<number>(1 << m).fill(Infinity);
    dp[0] = 0;

    for (let mask = 0; mask <= fullMask; mask++) {
        if (dp[mask] === Infinity) continue;

        for (const count of stickerCounts) {
            const remaining = count.slice();
            let nextMask = mask;

            for (let i = 0; i < m; i++) {
                if ((nextMask & (1 << i)) === 0) {
                    const index = target.charCodeAt(i) - 97;
                    if (remaining[index] > 0) {
                        remaining[index]--;
                        nextMask |= 1 << i;
                    }
                }
            }

            if (nextMask !== mask) {
                dp[nextMask] = Math.min(dp[nextMask], dp[mask] + 1);
            }
        }
    }

    return dp[fullMask] === Infinity ? -1 : dp[fullMask];
};
