function strWithout3a3b(a: number, b: number): string {
    let result = "";

    while (a > 0 || b > 0) {
        const n = result.length;
        const endsWithAA = n >= 2 && result[n - 1] === "a" && result[n - 2] === "a";
        const endsWithBB = n >= 2 && result[n - 1] === "b" && result[n - 2] === "b";

        if (endsWithAA) {
            result += "b";
            b--;
        } else if (endsWithBB) {
            result += "a";
            a--;
        } else if (a >= b && a > 0) {
            result += "a";
            a--;
        } else {
            result += "b";
            b--;
        }
    }

    return result;
}
