function earliestAndLatest(n: number, firstPlayer: number, secondPlayer: number): number[] {
    const memo = new Map<number, [number, number]>();
    const base = n + 1;

    function solve(size: number, a: number, b: number): [number, number] {
        if (a + b === size + 1) {
            return [1, 1];
        }

        const key = size * 1024 + a * 32 + b;
        const cached = memo.get(key);
        if (cached !== undefined) {
            return cached;
        }

        let possible = new Set<number>();
        possible.add(0);

        for (let i = 1; i <= Math.floor(size / 2); i++) {
            const j = size + 1 - i;
            const next = new Set<number>();

            const specialWinner =
                i === a || i === b || j === a || j === b;

            for (const code of possible) {
                const countA = Math.floor(code / base);
                const countB = code % base;

                const winners = specialWinner
                    ? [i === a || i === b ? i : j]
                    : [i, j];

                for (const winner of winners) {
                    const newCountA = countA + (winner < a ? 1 : 0);
                    const newCountB = countB + (winner < b ? 1 : 0);
                    next.add(newCountA * base + newCountB);
                }
            }

            possible = next;
        }

        if (size % 2 === 1) {
            const middle = Math.floor(size / 2) + 1;
            const next = new Set<number>();

            for (const code of possible) {
                const countA = Math.floor(code / base);
                const countB = code % base;
                const newCountA = countA + (middle < a ? 1 : 0);
                const newCountB = countB + (middle < b ? 1 : 0);
                next.add(newCountA * base + newCountB);
            }

            possible = next;
        }

        const nextSize = Math.ceil(size / 2);
        let earliest = Infinity;
        let latest = -Infinity;

        for (const code of possible) {
            const countA = Math.floor(code / base);
            const countB = code % base;

            const nextA = countA + 1;
            const nextB = countB + 1;

            const [early, late] = solve(nextSize, nextA, nextB);
            earliest = Math.min(earliest, early + 1);
            latest = Math.max(latest, late + 1);
        }

        const result: [number, number] = [earliest, latest];
        memo.set(key, result);
        return result;
    }

    return solve(n, firstPlayer, secondPlayer);
}
