        if (left !== -1 && ++indegree[left] > 1) return false;
        if (right !== -1 && ++indegree[right] > 1) return false;
    }

    let root = -1;
    for (let i = 0; i < n; i++) {
        if (indegree[i] === 0) {
            if (root !== -1) return false;
            root = i;
        }
