function isSolvable(words: string[], result: string): boolean {
    const charIndex = new Map<string, number>();
    const leading = new Set<number>();
    let count = 0;

    const register = (ch: string) => {
        if (!charIndex.has(ch)) {
            charIndex.set(ch, count++);
        }
    };

    for (const word of words) {
        for (const ch of word) register(ch);
        if (word.length > 1) {
            leading.add(charIndex.get(word[0])!);
        }
    }

    for (const ch of result) register(ch);
    if (result.length > 1) {
        leading.add(charIndex.get(result[0])!);
    }

    if (count > 10) return false;

    const assignment = new Array<number>(count).fill(-1);
    const used = new Array<boolean>(10).fill(false);
    const maxLength = Math.max(
        result.length,
        ...words.map(word => word.length)
    );

    const dfs = (column: number, carry: number): boolean => {
        if (column === maxLength) {
            return carry === 0;
        }

        const assignWords = (wordIndex: number, sum: number): boolean => {
            if (wordIndex === words.length) {
                const resultPosition = result.length - 1 - column;
                const requiredDigit = (sum + carry) % 10;
                const nextCarry = Math.floor((sum + carry) / 10);

                if (resultPosition < 0) {
                    return requiredDigit === 0 && dfs(column + 1, nextCarry);
                }

                const resultChar = result[resultPosition];
                const resultId = charIndex.get(resultChar)!;

                if (assignment[resultId] !== -1) {
                    return (
                        assignment[resultId] === requiredDigit &&
                        dfs(column + 1, nextCarry)
                    );
                }

                if (
                    used[requiredDigit] ||
                    (requiredDigit === 0 && leading.has(resultId))
                ) {
                    return false;
                }

                assignment[resultId] = requiredDigit;
                used[requiredDigit] = true;

                const solved = dfs(column + 1, nextCarry);

                assignment[resultId] = -1;
                used[requiredDigit] = false;

                return solved;
            }

            const word = words[wordIndex];
            const position = word.length - 1 - column;

            if (position < 0) {
                return assignWords(wordIndex + 1, sum);
            }

            const id = charIndex.get(word[position])!;

            if (assignment[id] !== -1) {
                return assignWords(
                    wordIndex + 1,
                    sum + assignment[id]
                );
            }

            for (let digit = 0; digit <= 9; digit++) {
                if (
                    used[digit] ||
                    (digit === 0 && leading.has(id))
                ) {
                    continue;
                }

                assignment[id] = digit;
                used[digit] = true;

                if (assignWords(wordIndex + 1, sum + digit)) {
                    return true;
                }

                assignment[id] = -1;
                used[digit] = false;
            }

            return false;
        };

        return assignWords(0, 0);
    };

    return dfs(0, 0);
};
