            const pattern = word.slice(0, i) + "*" + word.slice(i + 1);
            if (!patterns.has(pattern)) patterns.set(pattern, []);
            patterns.get(pattern)!.push(word);
        }
    }

    const queue: [string, number][] = [[beginWord, 1]];
    const visited = new Set<string>([beginWord]);
    let index = 0;

    while (index < queue.length) {
        const [word, distance] = queue[index++];

        for (let i = 0; i < word.length; i++) {
            const pattern = word.slice(0, i) + "*" + word.slice(i + 1);
            const neighbors = patterns.get(pattern);
            if (!neighbors) continue;

            patterns.delete(pattern);

            for (const nextWord of neighbors) {
                if (nextWord === endWord) return distance + 1;

                if (!visited.has(nextWord)) {
                    visited.add(nextWord);
                    queue.push([nextWord, distance + 1]);
                }
            }
        }
    }

    return 0;
};
